import sys

def main():
    m = sys.stdin.read().strip()
    if any(m[i] == '#' and m[i + 1] == '#' for i in range(len(m) - 1)):
        print(-1)
        return
    if m == '_' * len(m):
        print(0)
        return
    profile = []
    current_length = 0
    in_block = False
    for char in m:
        if char == '#':
            if not in_block:
                current_length = 0
                in_block = True
            current_length += 1
        elif char == '_':
            if in_block:
                profile.append(current_length)
                in_block = False
    if in_block:
        profile.append(current_length)
    print(len(profile))
    print(' '.join(map(str, profile)))

main()
